'use strict';
// The desktop splash screen shows before the server is up, so it cannot ask /locales.js. It gets the same words from the same
// language files: this writes desktop/ui/locales.js from public/locales/*.json (only the keys the splash uses).
// Run `npm run build:splash` after editing those keys; a test fails if the generated file is out of date.
const fs = require('fs');
const path = require('path');
const KEYS = ['splash.opening', 'splash.first_run', 'html.tagline'];
function build(root = path.join(__dirname, '..')) {
  const dir = path.join(root, 'public', 'locales'), out = {};
  for (const f of fs.readdirSync(dir).filter((x) => x.endsWith('.json')).sort()) {
    const all = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8'));
    out[f.slice(0, -5)] = Object.fromEntries(KEYS.map((k) => [k, all[k]]));
  }
  return '// Generated by scripts/build-splash-locales.js from public/locales/*.json. Do not edit.\nwindow.TW_SPLASH=' + JSON.stringify(out) + ';\n';
}
if (require.main === module) {
  const target = path.join(__dirname, '..', 'desktop', 'ui', 'locales.js');
  fs.writeFileSync(target, build());
  console.log('wrote ' + target);
}
module.exports = { build, KEYS };
